components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--accent, #20583c); color: white;
}
.ds-button-primary:hover { background: var(--accent-hover, #16432d); }
.ds-button-primary:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
.ds-button-primary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--surface, #fff); color: var(--ink, #19231c);
  border-color: var(--control, #87988a);
}
.ds-button-secondary:hover { background: var(--wash, #eaf2e6); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
.ds-button-secondary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-button-text {
  display: inline-flex; align-items: center; gap: 7px; min-height: 40px; padding: 4px 0; border: 0;
  color: var(--accent, #20583c); background: transparent; font: 650 13px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
  text-decoration: none; text-underline-offset: 0.2em;
}
.ds-button-text:hover { text-decoration: underline; }
.ds-button-text:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }

.ds-button-danger { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--red, #a62c48); color: white;
}
.ds-button-danger:hover { background: #8d223a; }
.ds-button-danger:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
.ds-button-danger:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-field {
  display: grid; gap: 7px; min-width: 0; margin-block: 17px;
  color: var(--ink, #19231c); font: 650 14px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-field input {
  box-sizing: border-box; min-width: 0; width: 100%; min-height: 44px; padding: 9px 11px;
  border: 1px solid var(--control, #87988a); border-radius: 8px; background: var(--surface, #fff);
  color: var(--ink, #19231c); font: 460 15px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
  caret-color: var(--accent, #20583c);
}
.ds-field input:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
.ds-field input:disabled { background: var(--paper, #f4f6f1); opacity: 0.75; }

.ds-studio-nav { display: grid; gap: 4px; }
.ds-studio-link {
  display: flex; align-items: center; gap: 10px; min-height: 44px; box-sizing: border-box;
  padding: 9px 11px; border-radius: 8px; color: var(--muted, #4d5c51);
  font: 610 14px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); text-decoration: none;
}
.ds-studio-link svg { flex-shrink: 0; }
.ds-studio-link:hover { background: var(--paper, #f4f6f1); color: var(--ink, #19231c); }
.ds-studio-link[aria-current] { background: var(--wash, #eaf2e6); color: var(--accent-hover, #16432d); font-weight: 720; }
.ds-studio-link:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
@media (max-width: 820px) {
  .ds-studio-nav { display: flex; flex-wrap: wrap; }
  .ds-studio-link { padding: 5px 9px; min-height: 39px; gap: 6px; font-size: 13px; }
  .ds-studio-link svg { width: 16px; }
}

.ds-status {
  display: inline-block; padding: 4px 9px; border-radius: 6px; background: var(--wash, #eaf2e6);
  color: var(--accent-hover, #16432d); font: 660 12px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-status::first-letter { text-transform: uppercase; }
@media (max-width: 370px) {
  .ds-status { padding-inline: 6px; font-size: 11px; }
}

.ds-preview-panel {
  min-width: 0; padding: 15px; border: 1px solid var(--line, #d9e1d7); border-radius: 12px;
  color: var(--ink, #19231c); background: var(--surface, #fff); font-family: var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-preview-panel h2 { margin: 0; font-size: 1.25rem; font-weight: 700; line-height: 1.22; letter-spacing: -0.023em; }
.ds-player-frame {
  position: relative; display: grid; grid-template-rows: 1fr auto; min-height: 154px; align-items: center; overflow: hidden;
  margin-block: 13px 15px; border-radius: 9px; background: var(--stage, #1c2921);
}
.ds-preview-placeholder {
  display: grid; justify-items: center; align-content: center; gap: 7px; padding: 17px 12px; text-align: center;
}
.ds-preview-placeholder small { color: var(--stage-accent, #dceadd); font-size: 13px; line-height: 1.55; }
.ds-choose-recording {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
  padding: 10px 16px; border: 1px solid var(--control, #87988a); border-radius: 9px; color: var(--ink, #19231c);
  background: var(--surface, #fff); font-family: inherit; font-size: 14px; font-weight: 680; line-height: 1.35; cursor: pointer; text-align: center;
}
.ds-choose-recording:hover { background: var(--wash, #eaf2e6); }
.ds-choose-recording:focus-visible { outline: 2px solid var(--accent, #20583c); outline-offset: 3px; }
.ds-local-caption { display: grid; justify-items: center; margin: 0 10px 11px; pointer-events: none; }
.ds-local-caption p {
  margin: 0; max-width: 100%; max-height: 6rem; overflow: hidden; padding: 4px 9px; border-radius: 4px;
  background: #1f152c; color: white; text-align: center; font-size: 18px; line-height: 2.06;
  text-shadow: 0 1px 3px #101810; white-space: pre-line; overflow-wrap: anywhere;
}
@media (max-width: 660px) {
  .ds-preview-panel { padding: 12px; }
}

.ds-format-selector { display:flex; flex-wrap:wrap; gap:3px; padding:3px; border:0; background:#f4f6f1; border-radius:8px; }
.ds-format-selector label { position:relative; cursor:pointer; }
.ds-format-selector label span { display:block; padding:8px 11px; border-radius:6px; color:#4d5c51; }
.ds-format-selector input { position:absolute; opacity:0; }
.ds-format-selector input:checked + span { background:#20583c; color:#fff; }
.ds-format-selector input:focus-visible + span { outline:2px solid #20583c; outline-offset:2px; }

.ds-caption-frame {
  position: relative; aspect-ratio: 16 / 8.8; width: 100%; overflow: hidden;
  border-radius: 10px; background: #1c2921; font-family: var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-caption-lines {
  position: absolute; inset: auto 9px clamp(12px, 5%, 28px); display: grid;
  justify-items: center; gap: 4px; text-align: center;
}
.ds-caption-lines span {
  padding: 4px 10px; border-radius: 4px; background: #101810; color: #fff;
  font-size: clamp(0.825rem, 1.45vw, 1.35rem); font-weight: 650; line-height: 1.38;
}
.ds-caption-lines span:lang(ur) {
  padding: 2px 12px 6px; font-family: CaptionUrdu, serif; font-size: clamp(1.05rem, 2.2vw, 2rem);
  font-weight: 400; line-height: 2.08; color: var(--stage, #1c2921); background: var(--stage-accent, #dceadd);
}
@media (max-width: 560px) {
  .ds-caption-frame { aspect-ratio: 16 / 9.5; }
}
